query TrackChangesWithParams($scope: ChangeTrackingScope!, $timeRange: String, $changeTypes: [ChangeType!]) {
  trackChanges(scope: $scope, timeRange: $timeRange, changeTypes: $changeTypes) {
    summary {
      totalChanges
      changesByType {
        type
        count
        percentage
      }
      mostActiveUsers
      mostChangedTables
    }
    changes {
      id
      timestamp
      user {
        id
        name
      }
      type
      entity {
        type
        id
        name
      }
      changes {
        field
        oldValue
        newValue
        operation
      }
      metadata {
        source
        version
        comments
      }
    }
    analytics {
      patterns {
        timeOfDay
        dayOfWeek
        frequency
      }
      trends {
        changeVelocity
        userActivity
        dataGrowth
      }
    }
    conflicts {
      potentialConflicts
      resolved
      pending
    }
  }
}
